def balanced(s):
    """Return True if all brackets in s are balanced, ignoring quoted text."""
    stack = []
    matching = {")": "(", "]": "[", "}": "{"}
    in_string = False
    escaped = False

    for ch in s:
        if in_string:
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == '"':
                in_string = False
        elif ch == '"':
            in_string = True
        elif ch in "([{":
            stack.append(ch)
        elif ch in ")]}":
            if not stack or stack.pop() != matching[ch]:
                return False

    return not in_string and not stack
